from solution import is_coprime


def test_issue_example_17_13():
    """Example: assert is_coprime(17,13) == True."""
    assert is_coprime(17, 13) == True  # gcd(17,13)=1, 1==1 so True


def test_issue_coprime_disjoint_factors():
    """Check whether the given numbers are co-prime or not."""
    assert is_coprime(8, 9) == True  # gcd(8,9)=1, 8=2*4 9=3*3 so True


def test_issue_not_coprime_even_numbers():
    """Check whether the given numbers are co-prime or not."""
    assert is_coprime(6, 10) == False  # gcd(6,10)=2, 2!=1 so False


def test_issue_not_coprime_shared_prime_factor():
    """Check whether the given numbers are co-prime or not."""
    assert is_coprime(15, 21) == False  # gcd(15,21)=3, 15=3*5 21=3*7 so False


def test_issue_one_is_coprime_with_any_number():
    """Check whether the given numbers are co-prime or not."""
    assert is_coprime(1, 100) == True  # gcd(1,100)=1, 1==1 so True


def test_issue_both_one_are_coprime():
    """Check whether the given numbers are co-prime or not."""
    assert is_coprime(1, 1) == True  # gcd(1,1)=1, 1==1 so True


def test_issue_identical_numbers_not_coprime():
    """Check whether the given numbers are co-prime or not."""
    assert is_coprime(7, 7) == False  # gcd(7,7)=7, 7!=1 so False


def test_issue_consecutive_numbers_are_coprime():
    """Check whether the given numbers are co-prime or not."""
    assert is_coprime(14, 15) == True  # gcd(14,15)=1, 14=2*7 15=3*5 so True


def test_issue_prime_multiple_not_coprime():
    """Check whether the given numbers are co-prime or not."""
    assert is_coprime(13, 26) == False  # gcd(13,26)=13, 26=2*13 so False


def test_contract_swapped_coprime_pair():
    """is_coprime(x, y) checks co-primeness regardless of argument order."""
    assert is_coprime(13, 17) == True  # gcd(13,17)=1, swapped distinct primes so True


def test_contract_swapped_not_coprime_pair():
    """is_coprime(x, y) checks co-primeness regardless of argument order."""
    assert is_coprime(10, 6) == False  # gcd(10,6)=2, 10=2*5 6=2*3 so False
